"""Buts, variables, premiers gestes et niveaux des trente laboratoires."""
from cours import ORDER


def _items(text):
    # The ASCII bar separates list entries, while the mathematical bar belongs
    # to an expression. Preserve these expressions before splitting the list.
    for expression in ('|x|','|u|','|k|','|f|','|f̂|','|H|'):
        text=text.replace(expression,expression.replace('|','∣'))
    return text.split('|')


def guide(purpose, objects, assumptions, techniques, steps, sup, spe, beyond, expected):
    return dict(purpose=purpose, objects=_items(objects),
                assumptions=_items(assumptions), techniques=_items(techniques),
                first_steps=steps, levels=dict(sup=sup, spe=spe,beyond=beyond),
                expected=expected, lesson_numbers=[])


